-- Parrot 6-hour rundown announcements.
-- One row per period; generated by agent/jobs/announcement-job.js.
create table if not exists parrot_announcements (
    id uuid primary key default gen_random_uuid(),
    created_at timestamptz not null default now(),
    period_start timestamptz not null,
    period_end timestamptz not null,
    rundown_text text not null,
    metadata jsonb
);

create index if not exists idx_parrot_announcements_period_end on parrot_announcements(period_end desc);
create index if not exists idx_parrot_announcements_period on parrot_announcements(period_start, period_end);

comment on table parrot_announcements is 'Parrot 6-hour rundown announcements. Generated by the agent every 6 hours from conversation history.';
